import { createHash, randomUUID } from "node:crypto";
import { PNG } from "pngjs";
import type { FastifyInstance } from "fastify";
import type { Pool } from "pg";
import { z } from "zod";
import { createRepositories, type MonthlyIllustrationContext, type MonthlyIllustrationView } from "@e4s/database";
import type { ObjectStorage } from "@e4s/storage";
import { createRoleGuard } from "../identity/policy.js";
import { EVIDENCE_BUCKET } from "../files/constants.js";

/**
 * Monthly core-word illustrations: one square 256px picture per core word,
 * generated by an image model (OPENAI_IMAGE_MODEL) while the resource pool is a
 * draft. Approval freezes the ready images into the curriculum contract; after
 * that nothing here can change them (VH: "không cho đổi ảnh"). Words that had no
 * ready picture at approval stay fillable (AI or upload) until they get one, and a
 * job running at approval time carries on for them.
 */

export const ILLUSTRATION_SIZE = 256;

export interface IllustrationProvider {
  readonly model: string;
  generate(prompt: string): Promise<{ body: Buffer; mimeType: string }>;
}

/**
 * OpenAI image generation. Key and model come from the environment.
 * - "images": POST /images/generations with an image model.
 * - "responses": POST /responses with a text model (e.g. gpt-6-luna, text output only)
 *   calling the built-in image_generation tool.
 * - "auto" (default): try the Images API, and switch to Responses for good when the
 *   model is not an image model.
 */
export function createOpenAiIllustrationProvider(options: { apiKey: string; model: string; baseUrl?: string; fetchImpl?: typeof fetch; timeoutMs?: number; api?: "auto" | "images" | "responses"; quality?: string }): IllustrationProvider {
  const baseUrl = (options.baseUrl ?? "https://api.openai.com/v1").replace(/\/$/u, "");
  const fetchImpl = options.fetchImpl ?? fetch;
  let mode: "auto" | "images" | "responses" = options.api ?? "auto";
  const headers = { "content-type": "application/json", authorization: `Bearer ${options.apiKey}` };

  const viaImages = async (prompt: string, signal: AbortSignal) => {
    const response = await fetchImpl(`${baseUrl}/images/generations`, { method: "POST", headers, body: JSON.stringify({ model: options.model, prompt, size: "1024x1024", n: 1 }), signal });
    if (!response.ok) {
      const detail = await response.text().catch(() => "");
      throw Object.assign(new Error(`IMAGE_PROVIDER_${response.status}: ${detail.slice(0, 300)}`), { notImageModel: response.status === 400 && /does not exist|not supported|invalid_value|image model/iu.test(detail) });
    }
    const payload = await response.json() as { data?: Array<{ b64_json?: string; url?: string }>; usage?: Record<string, unknown> };
    console.info(`[illustration-usage] ${JSON.stringify({ api: "images", model: options.model, usage: payload.usage ?? null })}`);
    const first = payload.data?.[0];
    if (first?.b64_json) return decoded(first.b64_json);
    if (first?.url) {
      const image = await fetchImpl(first.url, { signal });
      if (!image.ok) throw new Error(`IMAGE_DOWNLOAD_${image.status}`);
      const body = Buffer.from(await image.arrayBuffer());
      return { body, mimeType: sniffMime(body) };
    }
    throw new Error("IMAGE_PROVIDER_EMPTY");
  };

  const viaResponses = async (prompt: string, signal: AbortSignal) => {
    const response = await fetchImpl(`${baseUrl}/responses`, {
      method: "POST", headers, signal,
      body: JSON.stringify({
        model: options.model,
        input: prompt,
        tools: [{ type: "image_generation", size: "1024x1024", quality: options.quality ?? "low", output_format: "png" }],
        tool_choice: "required"
      })
    });
    if (!response.ok) {
      const detail = await response.text().catch(() => "");
      throw new Error(`IMAGE_PROVIDER_${response.status}: ${detail.slice(0, 300)}`);
    }
    const payload = await response.json() as { output?: Array<{ type?: string; result?: string | null; status?: string; size?: string; quality?: string }>; usage?: Record<string, unknown> };
    // One log line per picture so the real cost can be measured from the provider's own usage numbers.
    const call0 = payload.output?.find((item) => item.type === "image_generation_call");
    console.info(`[illustration-usage] ${JSON.stringify({ api: "responses", model: options.model, usage: payload.usage ?? null, image: call0 ? { size: call0.size ?? null, quality: call0.quality ?? null, status: call0.status ?? null } : null })}`);
    const call = payload.output?.find((item) => item.type === "image_generation_call" && typeof item.result === "string" && item.result);
    if (!call?.result) throw new Error("IMAGE_PROVIDER_EMPTY: the model returned no image_generation_call result");
    return decoded(call.result);
  };

  return {
    model: options.model,
    async generate(prompt) {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), options.timeoutMs ?? 180_000);
      try {
        if (mode === "responses") return await viaResponses(prompt, controller.signal);
        try {
          return await viaImages(prompt, controller.signal);
        } catch (error) {
          if (mode !== "auto" || !(error as { notImageModel?: boolean }).notImageModel) throw error;
          mode = "responses";
          return await viaResponses(prompt, controller.signal);
        }
      } finally {
        clearTimeout(timer);
      }
    }
  };
}

function decoded(base64: string): { body: Buffer; mimeType: string } {
  const body = Buffer.from(base64, "base64");
  return { body, mimeType: sniffMime(body) };
}

export function createIllustrationProviderFromEnvironment(env: NodeJS.ProcessEnv): IllustrationProvider | undefined {
  const apiKey = env.OPENAI_API_KEY?.trim();
  const model = env.OPENAI_IMAGE_MODEL?.trim();
  if (!apiKey || !model) return undefined;
  const api = env.OPENAI_IMAGE_API?.trim();
  return createOpenAiIllustrationProvider({
    apiKey, model,
    ...(env.OPENAI_BASE_URL?.trim() ? { baseUrl: env.OPENAI_BASE_URL.trim() } : {}),
    ...(api === "images" || api === "responses" ? { api } : {}),
    ...(env.OPENAI_IMAGE_QUALITY?.trim() ? { quality: env.OPENAI_IMAGE_QUALITY.trim() } : {})
  });
}

/**
 * One simple, icon-like picture per word, readable as a small thumbnail on a
 * vocabulary card: one subject, at most 2-3 elements, no busy office scene.
 */
export function buildIllustrationPrompt(context: Pick<MonthlyIllustrationContext, "theme">, term: { word: string; meaning: string; type: string }, hint?: string): string {
  return [
    "Simple flashcard icon illustrating one English vocabulary word for Vietnamese office workers.",
    `Meaning to show: "${term.meaning}" (the English ${term.type || "word"} "${term.word}"). Workplace context: ${context.theme.title}.`,
    "Simple but complete: one main subject plus at most 2 supporting elements chosen so the picture shows this exact meaning and not a neighbouring word. Think: who or what, doing what, to what. Examples: stakeholder = a project folder in the centre with three different people around it, each pointing at it; escalate = a small problem card moving up steps from one person to a higher manager; scope = a project box with items inside a clear boundary and one item crossed out outside it; milestone = a road with a flag at one marked point.",
    "Avoid clutter: no room, no furniture, no plants, no decoration, no screens full of detail, no extra people beyond what the meaning needs.",
    "Style (same for every word): flat vector icon, thick dark outlines, large simple shapes, few bright colours, high contrast, no pixel art, no gradients, no shading detail, subject centred and filling most of the square, plain single-colour light background. It must stay readable when shown as a 64x64 thumbnail.",
    hint?.trim() ? `Operator note: ${hint.trim().slice(0, 300)}.` : "",
    "Absolutely no text: no letters, words, numbers, labels, captions, signs, logos or speech bubbles anywhere in the image."
  ].filter(Boolean).join("\n");
}

/** Box-filter downscale of a square PNG to `size`×`size` (pixel art stays crisp). Non-PNG input is returned unchanged. */
export function downscalePng(input: Buffer, size = ILLUSTRATION_SIZE): { body: Buffer; mimeType: string } {
  if (sniffMime(input) !== "image/png") return { body: input, mimeType: sniffMime(input) };
  const source = PNG.sync.read(input);
  const side = Math.min(source.width, source.height);
  if (side <= size) return { body: input, mimeType: "image/png" };
  const offsetX = Math.floor((source.width - side) / 2);
  const offsetY = Math.floor((source.height - side) / 2);
  const target = new PNG({ width: size, height: size });
  const scale = side / size;
  for (let y = 0; y < size; y += 1) {
    for (let x = 0; x < size; x += 1) {
      const x0 = offsetX + Math.floor(x * scale), x1 = offsetX + Math.max(Math.floor((x + 1) * scale), Math.floor(x * scale) + 1);
      const y0 = offsetY + Math.floor(y * scale), y1 = offsetY + Math.max(Math.floor((y + 1) * scale), Math.floor(y * scale) + 1);
      let r = 0, g = 0, b = 0, a = 0, count = 0;
      for (let sy = y0; sy < y1; sy += 1) {
        for (let sx = x0; sx < x1; sx += 1) {
          const index = (sy * source.width + sx) * 4;
          r += source.data[index]!; g += source.data[index + 1]!; b += source.data[index + 2]!; a += source.data[index + 3]!;
          count += 1;
        }
      }
      const out = (y * size + x) * 4;
      target.data[out] = Math.round(r / count); target.data[out + 1] = Math.round(g / count);
      target.data[out + 2] = Math.round(b / count); target.data[out + 3] = Math.round(a / count);
    }
  }
  return { body: PNG.sync.write(target), mimeType: "image/png" };
}

function sniffMime(body: Buffer): string {
  if (body.subarray(0, 8).equals(Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]))) return "image/png";
  if (body[0] === 0xff && body[1] === 0xd8) return "image/jpeg";
  if (body.subarray(0, 4).toString("ascii") === "RIFF" && body.subarray(8, 12).toString("ascii") === "WEBP") return "image/webp";
  return "application/octet-stream";
}

type Repositories = ReturnType<typeof createRepositories>;

/**
 * Illustration jobs alive in this API process: framework id -> normalised words still queued
 * or being drawn. A pending/generating row whose word is not here has no job behind it
 * (the job ended, or the API restarted) and is offered again as "missing".
 */
const activeIllustrationJobs = new Map<string, Set<string>>();

/** Same normalisation as the repository's month_framework_images.word (kept local: route tests mock @e4s/database). */
function normalizeIllustrationWord(word: string): string {
  return word.trim().toLocaleLowerCase("en-US");
}

/** A word stuck in "generating" this long has outlived the provider timeout and one retry. */
export const ILLUSTRATION_STALE_MS = 10 * 60_000;

export function illustrationJobRunning(frameworkId: string): boolean {
  return activeIllustrationJobs.has(frameworkId);
}

/** Marks a job as live for these words (exported for tests; the generate route does this itself). */
export function trackIllustrationJob(frameworkId: string, words: readonly string[]): () => void {
  activeIllustrationJobs.set(frameworkId, new Set(words.map(normalizeIllustrationWord)));
  return () => { activeIllustrationJobs.delete(frameworkId); };
}

/** Maps pending/generating rows without a live job (or stuck far too long) to "missing", so they can be generated again. */
export function withLiveIllustrationStates(frameworkId: string, images: readonly MonthlyIllustrationView[], now = Date.now()): MonthlyIllustrationView[] {
  const live = activeIllustrationJobs.get(frameworkId);
  return images.map((image) => {
    if (image.status !== "pending" && image.status !== "generating") return image;
    const queued = live?.has(normalizeIllustrationWord(image.word)) ?? false;
    const stuck = image.status === "generating" && image.updatedAt !== undefined && now - Date.parse(image.updatedAt) > ILLUSTRATION_STALE_MS;
    return queued && !stuck ? image : { ...image, status: "missing" as const, error: "Bị gián đoạn, hãy sinh lại." };
  });
}

/** Words still queued or being drawn by a live job (what an approval would have to wait for). */
export function illustrationsInProgress(frameworkId: string, images: readonly MonthlyIllustrationView[]): number {
  return withLiveIllustrationStates(frameworkId, images).filter((image) => image.status === "pending" || image.status === "generating").length;
}

/**
 * Generates the given words with bounded concurrency; each word's status is persisted as it goes.
 * A refused write (resources approved meanwhile and the word now has a picture, or retired) skips
 * that word only: an approval mid-run must not strand the words that still have no picture.
 */
export async function runMonthlyIllustrationJob(input: {
  repositories: Repositories;
  storage: ObjectStorage;
  provider: IllustrationProvider;
  context: MonthlyIllustrationContext;
  words: ReadonlyArray<{ word: string; meaning: string; type: string }>;
  actorId: string;
  hint?: string;
  concurrency?: number;
}): Promise<{ ready: number; failed: number }> {
  const frameworkId = input.context.frameworkId;
  const live = activeIllustrationJobs.get(frameworkId);
  const done = (word: string) => { live?.delete(normalizeIllustrationWord(word)); };
  const queue: Array<{ word: string; meaning: string; type: string }> = [];
  let ready = 0;
  let failed = 0;
  for (const term of input.words) {
    if (await input.repositories.monthlyContent.saveFrameworkIllustration({ frameworkId, word: term.word, status: "pending", actorId: input.actorId, ...(input.hint ? { hint: input.hint } : {}) })) queue.push(term);
    else done(term.word);
  }
  const worker = async () => {
    for (let term = queue.shift(); term; term = queue.shift()) {
      // Refused = this word got a picture that approval locked meanwhile: skip it, keep going for the rest.
      if (!(await input.repositories.monthlyContent.saveFrameworkIllustration({ frameworkId, word: term.word, status: "generating", actorId: input.actorId }))) { done(term.word); continue; }
      try {
        const raw = await generateWithRetry(input.provider, buildIllustrationPrompt(input.context, term, input.hint));
        const image = downscalePng(raw.body);
        const extension = image.mimeType === "image/png" ? ".png" : image.mimeType === "image/jpeg" ? ".jpg" : ".webp";
        const objectKey = `content-media/${input.actorId}/illustration-${randomUUID()}${extension}`;
        await input.storage.putObject({ bucket: EVIDENCE_BUCKET, objectKey, body: image.body, mimeType: image.mimeType });
        const saved = await input.repositories.files.createForOwner({
          id: randomUUID(), ownerUserId: input.actorId, purpose: "content_media", bucket: EVIDENCE_BUCKET,
          objectKey, mimeType: image.mimeType, sizeBytes: image.body.length, sha256: createHash("sha256").update(image.body).digest("hex")
        });
        if (!saved) throw new Error("ILLUSTRATION_FILE_NOT_SAVED");
        if (await input.repositories.monthlyContent.saveFrameworkIllustration({ frameworkId, word: term.word, status: "ready", source: "ai", artifactKey: objectKey, mimeType: image.mimeType, actorId: input.actorId })) ready += 1;
      } catch (error) {
        failed += 1;
        await input.repositories.monthlyContent.saveFrameworkIllustration({ frameworkId, word: term.word, status: "failed", error: error instanceof Error ? error.message.slice(0, 300) : "ILLUSTRATION_FAILED", actorId: input.actorId });
      } finally {
        done(term.word);
      }
    }
  };
  await Promise.all(Array.from({ length: Math.max(1, Math.min(input.concurrency ?? 6, queue.length || 1)) }, worker));
  return { ready, failed };
}

async function generateWithRetry(provider: IllustrationProvider, prompt: string): Promise<{ body: Buffer; mimeType: string }> {
  try {
    return await provider.generate(prompt);
  } catch (error) {
    // One retry covers transient 429/5xx; content refusals fail fast on the second try too.
    await new Promise((resolve) => setTimeout(resolve, 2_000));
    return provider.generate(prompt);
  }
}

const frameworkParams = z.object({ id: z.uuid() });
const generateInput = z.object({
  /** Words to (re)generate; omitted = every word without a ready image. */
  words: z.array(z.string().trim().min(1).max(80)).max(200).optional(),
  hint: z.string().trim().max(300).optional()
});
const uploadInput = z.object({ word: z.string().trim().min(1).max(80), artifactKey: z.string().trim().startsWith("content-media/").max(512) });
const removeInput = z.object({ word: z.string().trim().min(1).max(80) });

export function registerMonthlyIllustrationRoutes(app: FastifyInstance, pool: Pool, storage?: ObjectStorage, provider?: IllustrationProvider): void {
  const repositories = createRepositories(pool);
  const operator = createRoleGuard(pool, ["operator", "manager"]);
  const contentOperator = createRoleGuard(pool, ["operator"]);
  const liveImages = async (actorId: string, id: string) => withLiveIllustrationStates(id, await repositories.monthlyContent.listFrameworkIllustrations(actorId, id));
  /** A draft is fully editable; approved resources still take pictures for words that have none; retired ones take nothing. */
  const fillable = (context: MonthlyIllustrationContext) => !context.locked || context.status === "approved";

  app.get("/api/v1/content/month-frameworks/:id/illustrations", { preHandler: operator }, async (request) => {
    const { id } = frameworkParams.parse(request.params);
    // Rows left pending/generating without a live job (job ended, API restarted) are offered again as missing.
    const images = await liveImages(request.e4sSession!.user.id, id);
    const locked = images.some((image) => image.frameworkLocked ?? image.locked);
    return {
      images, running: illustrationJobRunning(id), available: Boolean(provider && storage), model: provider?.model ?? null,
      /** Words that can still get a picture (missing or failed, not locked). */
      fillable: images.filter((image) => !image.locked && (image.status === "missing" || image.status === "failed")).length,
      /** Resources approved (or retired): pictures that exist can no longer change. */
      locked
    };
  });

  app.post("/api/v1/content/month-frameworks/:id/illustrations/generate", { preHandler: contentOperator }, async (request, reply) => {
    const { id } = frameworkParams.parse(request.params);
    const body = generateInput.safeParse(request.body ?? {});
    if (!body.success) return reply.code(400).send({ code: "ILLUSTRATION_INPUT_INVALID" });
    const actorId = request.e4sSession!.user.id;
    const context = await repositories.monthlyContent.frameworkIllustrationContext(actorId, id);
    if (!fillable(context)) return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    if (!provider || !storage) return reply.code(503).send({ code: "ILLUSTRATION_PROVIDER_UNAVAILABLE" });
    if (illustrationJobRunning(id)) return reply.code(409).send({ code: "ILLUSTRATION_JOB_RUNNING" });
    const current = await liveImages(actorId, id);
    const imageOf = (termId: string) => current.find((image) => image.coreTermId === termId);
    const requested = body.data.words?.map(normalizeIllustrationWord);
    const words = context.coreTerms.filter((term) => requested
      ? requested.includes(normalizeIllustrationWord(term.word))
      : imageOf(term.id)?.status !== "ready");
    // After approval an existing picture is locked: redrawing it is refused, filling a missing one is not.
    if (context.locked && words.some((term) => imageOf(term.id)?.locked || imageOf(term.id)?.status === "ready")) return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    if (!words.length) return { started: false, count: 0 };
    const untrack = trackIllustrationJob(id, words.map((term) => term.word));
    void runMonthlyIllustrationJob({ repositories, storage, provider, context, words, actorId, ...(body.data.hint ? { hint: body.data.hint } : {}), concurrency: Number(process.env.IMAGE_GENERATION_CONCURRENCY ?? 6) })
      .catch((error) => request.log.error({ err: error }, "monthly illustration job failed"))
      .finally(untrack);
    return reply.code(202).send({ started: true, count: words.length });
  });

  /** Replace one word's picture with an uploaded image (draft; once approved, only for a word without a picture). */
  app.put("/api/v1/content/month-frameworks/:id/illustrations", { preHandler: contentOperator }, async (request, reply) => {
    const { id } = frameworkParams.parse(request.params);
    const body = uploadInput.safeParse(request.body);
    if (!body.success) return reply.code(400).send({ code: "ILLUSTRATION_INPUT_INVALID" });
    const actorId = request.e4sSession!.user.id;
    const context = await repositories.monthlyContent.frameworkIllustrationContext(actorId, id);
    if (!fillable(context)) return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    const term = context.coreTerms.find((core) => normalizeIllustrationWord(core.word) === normalizeIllustrationWord(body.data.word));
    if (!term) return reply.code(404).send({ code: "CORE_WORD_NOT_FOUND" });
    if (context.locked) {
      const image = (await liveImages(actorId, id)).find((item) => item.coreTermId === term.id);
      if (image?.locked || image?.status === "ready") return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    }
    if (!(await repositories.files.ownedBy(actorId, "content_media", body.data.artifactKey))) return reply.code(400).send({ code: "ILLUSTRATION_FILE_NOT_OWNED" });
    // The repository refuses the write when the word got a locked picture meanwhile.
    if (!(await repositories.monthlyContent.saveFrameworkIllustration({ frameworkId: id, word: body.data.word, status: "ready", source: "upload", artifactKey: body.data.artifactKey, actorId }))) return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    return { images: await liveImages(actorId, id) };
  });

  /** Remove one word's picture (draft only); the word then shows text only unless a new picture is added. */
  app.delete("/api/v1/content/month-frameworks/:id/illustrations", { preHandler: contentOperator }, async (request, reply) => {
    const { id } = frameworkParams.parse(request.params);
    const body = removeInput.safeParse(request.body);
    if (!body.success) return reply.code(400).send({ code: "ILLUSTRATION_INPUT_INVALID" });
    const actorId = request.e4sSession!.user.id;
    const context = await repositories.monthlyContent.frameworkIllustrationContext(actorId, id);
    if (context.locked) return reply.code(409).send({ code: "MONTHLY_RESOURCES_LOCKED" });
    if (illustrationJobRunning(id)) return reply.code(409).send({ code: "ILLUSTRATION_JOB_RUNNING" });
    if (!context.coreTerms.some((term) => term.word.trim().toLocaleLowerCase("en-US") === body.data.word.toLocaleLowerCase("en-US"))) return reply.code(404).send({ code: "CORE_WORD_NOT_FOUND" });
    await repositories.monthlyContent.removeFrameworkIllustration({ frameworkId: id, word: body.data.word });
    return { images: await liveImages(actorId, id) };
  });
}
